import math
import torch
import torch.nn as nn
from torch.nn import init
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE_RAW = r"""
   7: .version 8.0
   8: .target sm_89
   9: .address_size 64
  10: .extern .shared .align 16 .b8 smem[];
  11: .visible .entry conv_transpose3d_kernel(
  12:     .param .u64 x_ptr,
  13:     .param .u64 w_ptr,
  14:     .param .u64 b_ptr,
  15:     .param .u64 y_ptr,
  16:     .param .u32 N,
  17:     .param .u32 C_in,
  18:     .param .u32 C_out,
  19:     .param .u32 D_in,
  20:     .param .u32 H_in,
  21:     .param .u32 W_in,
  22:     .param .u32 D_out,
  23:     .param .u32 H_out,
  24:     .param .u32 W_out,
  25:     .param .u32 K,
  26:     .param .u32 stride,
  27:     .param .u32 padding,
  28:     .param .u32 groups,
  29:     .param .u32 has_bias
  30: )
  31: {
  32:     // Registers
  33:     .reg .pred  p_tmp, p_active, p_hasBias;
  34:     .reg .b32   rN, rCin, rCout, rDin, rHin, rWin, rDout, rHout, rWout;
  35:     .reg .b32   rK, rS, rP, rG, rHasBias;
  36:     .reg .b32   r_tid, r_bdim, r_bidx, r_wi;
  37:     .reg .b32   r_ho, r_z, r_totalCD, r_totalAll;
  38:     .reg .b32   r_n, r_co, r_do, r_tmp32, r_rem, r_cpg, r_cig;
  39:     .reg .b32   r_grp, r_co_g, r_in_cg, r_ci;
  40:     .reg .b32   r_kd, r_kh, r_kw;
  41:     .reg .s32   t_d_num, t_h_num, t_w_num, t_div, t_rem, t_d_base, t_h_base, t_w_base;
  42:     .reg .b32   r_di, r_hi, r_wii;
  43:     .reg .b32   r_idx, r_tmpA, r_tmpB, r_tmpC, r_tmpD;
  44:     .reg .b32   rK2, rK3, rWN, r_t;
  45:     .reg .b32   r_kd_start, r_kh_start, r_kw_start;
  46:     .reg .s32   m_d, m_h, m_w, m_d_min, m_d_max, m_h_min, m_h_max, m_w_min, m_w_max;
  47:     .reg .s32   kd_s, kh_s, kw_s, t_tmp_s32, t_tmpA_s32, t_tmpB_s32, t_tmpC_s32, sDin, sHin, sWin;
  48:     .reg .b64   px, pw, pb, py;
  49:     .reg .b64   addr, off, smem_ptr;
  50:     .reg .f32   f_sum, f_x, f_w, f_b;
  51:     // Load params
  52:     ld.param.u64 px, [x_ptr];
  53:     ld.param.u64 pw, [w_ptr];
  54:     ld.param.u64 pb, [b_ptr];
  55:     ld.param.u64 py, [y_ptr];
  56:     ld.param.u32 rN, [N];
  57:     ld.param.u32 rCin, [C_in];
  58:     ld.param.u32 rCout, [C_out];
  59:     ld.param.u32 rDin, [D_in];
  60:     ld.param.u32 rHin, [H_in];
  61:     ld.param.u32 rWin, [W_in];
  62:     ld.param.u32 rDout, [D_out];
  63:     ld.param.u32 rHout, [H_out];
  64:     ld.param.u32 rWout, [W_out];
  65:     ld.param.u32 rK, [K];
  66:     ld.param.u32 rS, [stride];
  67:     ld.param.u32 rP, [padding];
  68:     ld.param.u32 rG, [groups];
  69:     ld.param.u32 rHasBias, [has_bias];
  70:     // Thread/block indices
  71:     mov.u32 r_tid, %tid.x;
  72:     mov.u32 r_bdim, %ntid.x;
  73:     mov.u32 r_bidx, %ctaid.x;
  74:     mad.lo.s32 r_wi, r_bidx, r_bdim, r_tid; // width index
  75:     mov.u32 r_ho, %ctaid.y;                 // height index
  76:     mov.u32 r_z, %ctaid.z;                  // packed (n,co,do)
  77:     // Compute totalCD and totalAll (for decode only)
  78:     mul.lo.u32 r_totalCD, rCout, rDout;
  79:     mul.lo.u32 r_totalAll, rN, r_totalCD;
  80:     // Decode n, co, do from z
  81:     div.u32 r_n, r_z, r_totalCD;
  82:     mul.lo.u32 r_tmp32, r_n, r_totalCD;
  83:     sub.s32 r_rem, r_z, r_tmp32;
  84:     div.u32 r_co, r_rem, rDout;
  85:     mul.lo.u32 r_tmp32, r_co, rDout;
  86:     sub.s32 r_do, r_rem, r_tmp32;
  87:     // Group/channel partitioning
  88:     div.u32 r_cpg, rCout, rG;    // channels per group (out)
  89:     div.u32 r_cig, rCin, rG;     // channels per group (in)
  90:     div.u32 r_grp, r_co, r_cpg;  // group index
  91:     mul.lo.u32 r_tmp32, r_grp, r_cpg;
  92:     sub.s32 r_co_g, r_co, r_tmp32; // co within group
  93:     // Precompute K^2 and K^3 and total weights to stage
  94:     mul.lo.u32 rK2, rK, rK;
  95:     mul.lo.u32 rK3, rK2, rK;
  96:     mul.lo.u32 rWN, r_cig, rK3; // number of weights to stage for this (co_g)
  97:     // Get base shared memory pointer
     mov.u64 smem_ptr, smem;
  99:     // Cooperative stage of weights w[ci, co_g, kd, kh, kw] for all ci in group into shared memory
 100:     mov.u32 r_t, r_tid;
 101: L_STAGE:
 102:     setp.ge.u32 p_tmp, r_t, rWN;
 103:     @p_tmp bra L_STAGE_END;
 104:         // Decompose linear index r_t into (ci_g, kd, kh, kw)
 105:         div.u32 r_tmpA, r_t, rK3;          // r_tmpA = ci_g
 106:         mul.lo.u32 r_tmpB, r_tmpA, rK3;    // r_tmpB = ci_g*K^3
 107:         sub.s32 r_tmpC, r_t, r_tmpB;       // r_tmpC = rem0
 108:         div.u32 r_kd, r_tmpC, rK2;
 109:         mul.lo.u32 r_tmpB, r_kd, rK2;
 110:         sub.s32 r_tmpD, r_tmpC, r_tmpB;    // r_tmpD = rem1
 111:         div.u32 r_kh, r_tmpD, rK;
 112:         mul.lo.u32 r_tmpB, r_kh, rK;
 113:         sub.s32 r_kw, r_tmpD, r_tmpB;
 114:         // ci = grp*cig + ci_g
 115:         mul.lo.u32 r_tmpB, r_grp, r_cig;
 116:         add.u32    r_ci,  r_tmpB, r_tmpA;
 117:         // Global w index: (((((ci*cpg + co_g)*K + kd)*K + kh)*K) + kw)
 118:         mul.lo.u32 r_tmpB, r_ci, r_cpg;
 119:         add.u32    r_tmpB, r_tmpB, r_co_g;
 120:         mul.lo.u32 r_tmpB, r_tmpB, rK;
 121:         add.u32    r_tmpB, r_tmpB, r_kd;
 122:         mul.lo.u32 r_tmpB, r_tmpB, rK;
 123:         add.u32    r_tmpB, r_tmpB, r_kh;
 124:         mul.lo.u32 r_tmpB, r_tmpB, rK;
 125:         add.u32    r_tmpB, r_tmpB, r_kw;
 126:         mul.wide.u32 off, r_tmpB, 4;
 127:         add.s64 addr, pw, off;
 128:         ld.global.f32 f_w, [addr];
 129:         // Store to shared memory at offset r_t
 130:         mul.wide.u32 off, r_t, 4;
 131:         add.s64 addr, smem_ptr, off;
 132:         st.shared.f32 [addr], f_w;
 133:         // Next
 134:         add.u32 r_t, r_t, r_bdim;
 135:         bra L_STAGE;
 136: L_STAGE_END:
 137:     // Ensure all weights are staged
 138:     bar.sync 0;
 139:     // Active thread predicate (width tail handling)
 140:     setp.lt.u32 p_active, r_wi, rWout;
 141:     // Initialize accumulator with bias (if any) for active threads
 142:     mov.f32 f_sum, 0f00000000;
 143:     @!p_active bra SKIP_BIAS;
 144:         setp.ne.u32 p_hasBias, rHasBias, 0;
 145:         @!p_hasBias bra SKIP_BIAS;
 146:             mul.wide.u32 off, r_co, 4;
 147:             add.s64 addr, pb, off;
 148:             ld.global.f32 f_b, [addr];
 149:             mov.f32 f_sum, f_b;
 150:     SKIP_BIAS:
 151:     // Skip compute for inactive threads
 152:     @!p_active bra SKIP_COMPUTE;
 153:     // Precompute stride residue and base indices for D, H, W
 154:     add.s32 t_d_num, r_do, rP;
 155:     rem.s32 t_rem, t_d_num, rS;
 156:     mov.u32 r_kd_start, t_rem;
 157:     div.s32 t_div, t_d_num, rS;
 158:     mov.s32 t_d_base, t_div;
 159:     add.s32 t_h_num, r_ho, rP;
 160:     rem.s32 t_rem, t_h_num, rS;
 161:     mov.u32 r_kh_start, t_rem;
 162:     div.s32 t_div, t_h_num, rS;
 163:     mov.s32 t_h_base, t_div;
 164:     add.s32 t_w_num, r_wi, rP;
 165:     rem.s32 t_rem, t_w_num, rS;
 166:     mov.u32 r_kw_start, t_rem;
 167:     div.s32 t_div, t_w_num, rS;
 168:     mov.s32 t_w_base, t_div;
 169:     // Compute valid iteration ranges per dimension to avoid in-loop bounds checks
 170:     // m_d range
 171:     // m_dK = (K-1 - kd_start)/S
 172:     add.s32 t_tmp_s32, rK, -1;
 173:     sub.s32 t_tmp_s32, t_tmp_s32, r_kd_start;
 174:     div.s32 t_div, t_tmp_s32, rS;
 175:     // m_d_min = max(0, t_d_base - (Din-1))
 176:     cvt.s32.u32 sDin, rDin;
 177:     add.s32 t_tmpA_s32, sDin, -1;
 178:     sub.s32 t_tmpA_s32, t_d_base, t_tmpA_s32;
 179:     mov.s32 m_d_min, t_tmpA_s32;
 180:     setp.lt.s32 p_tmp, m_d_min, 0;
 181:     @p_tmp mov.s32 m_d_min, 0;
 182:     // m_d_max = min(m_dK, t_d_base)
 183:     mov.s32 m_d_max, t_div;
 184:     setp.gt.s32 p_tmp, m_d_max, t_d_base;
 185:     @p_tmp mov.s32 m_d_max, t_d_base;
 186:     // m_h range
 187:     add.s32 t_tmp_s32, rK, -1;
 188:     sub.s32 t_tmp_s32, t_tmp_s32, r_kh_start;
 189:     div.s32 t_div, t_tmp_s32, rS;         // m_hK in t_div
 190:     cvt.s32.u32 sHin, rHin;
 191:     add.s32 t_tmpB_s32, sHin, -1;
 192:     sub.s32 t_tmpB_s32, t_h_base, t_tmpB_s32;
 193:     mov.s32 m_h_min, t_tmpB_s32;
 194:     setp.lt.s32 p_tmp, m_h_min, 0;
 195:     @p_tmp mov.s32 m_h_min, 0;
 196:     mov.s32 m_h_max, t_div;
 197:     setp.gt.s32 p_tmp, m_h_max, t_h_base;
 198:     @p_tmp mov.s32 m_h_max, t_h_base;
 199:     // m_w range
 200:     add.s32 t_tmp_s32, rK, -1;
 201:     sub.s32 t_tmp_s32, t_tmp_s32, r_kw_start;
 202:     div.s32 t_div, t_tmp_s32, rS;         // m_wK in t_div
 203:     cvt.s32.u32 sWin, rWin;
 204:     add.s32 t_tmpC_s32, sWin, -1;
 205:     sub.s32 t_tmpC_s32, t_w_base, t_tmpC_s32;
 206:     mov.s32 m_w_min, t_tmpC_s32;
 207:     setp.lt.s32 p_tmp, m_w_min, 0;
 208:     @p_tmp mov.s32 m_w_min, 0;
 209:     mov.s32 m_w_max, t_div;
 210:     setp.gt.s32 p_tmp, m_w_max, t_w_base;
 211:     @p_tmp mov.s32 m_w_max, t_w_base;
 212:     // If any dimension has empty range, skip compute
 213:     setp.gt.s32 p_tmp, m_d_min, m_d_max;
 214:     @p_tmp bra SKIP_COMPUTE;
 215:     setp.gt.s32 p_tmp, m_h_min, m_h_max;
 216:     @p_tmp bra SKIP_COMPUTE;
 217:     setp.gt.s32 p_tmp, m_w_min, m_w_max;
 218:     @p_tmp bra SKIP_COMPUTE;
 219:     // Loop over input channels within group
 220:     mov.u32 r_in_cg, 0;
 221: L_IN_CG:
 222:     setp.ge.u32 p_tmp, r_in_cg, r_cig;
 223:     @p_tmp bra L_END_IN_CG;
 224:         // ci = grp*cig + in_cg
 225:         mul.lo.u32 r_tmp32, r_grp, r_cig;
 226:         add.u32 r_ci, r_tmp32, r_in_cg;
 227:         // kd/kh/kw loops using precomputed valid m ranges
 228:         mov.s32 m_d, m_d_min;
 229:     L_MD2:
 230:         setp.gt.s32 p_tmp, m_d, m_d_max;
 231:         @p_tmp bra L_END_MD2;
 232:             // kd = kd_start + m_d * S; di = t_d_base - m_d
 233:             mad.lo.s32 kd_s, m_d, rS, r_kd_start;
 234:             sub.s32 t_tmpA_s32, t_d_base, m_d;
 235:             cvt.u32.s32 r_di, t_tmpA_s32;
 236:             cvt.u32.s32 r_kd, kd_s;
 237:             // kh loop
 238:             mov.s32 m_h, m_h_min;
 239:         L_MH2:
 240:             setp.gt.s32 p_tmp, m_h, m_h_max;
 241:             @p_tmp bra L_END_MH2;
 242:                 // kh = kh_start + m_h * S; hi = t_h_base - m_h
 243:                 mad.lo.s32 kh_s, m_h, rS, r_kh_start;
 244:                 sub.s32 t_tmpB_s32, t_h_base, m_h;
 245:                 cvt.u32.s32 r_hi, t_tmpB_s32;
 246:                 cvt.u32.s32 r_kh, kh_s;
 247:                 // kw loop
 248:                 mov.s32 m_w, m_w_min;
 249:             L_MW2:
 250:                 setp.gt.s32 p_tmp, m_w, m_w_max;
 251:                 @p_tmp bra L_END_MW2;
 252:                     // kw = kw_start + m_w * S; wi = t_w_base - m_w
 253:                     mad.lo.s32 kw_s, m_w, rS, r_kw_start;
 254:                     sub.s32 t_tmpC_s32, t_w_base, m_w;
 255:                     cvt.u32.s32 r_wii, t_tmpC_s32;
 256:                     cvt.u32.s32 r_kw, kw_s;
 257:                     // Load x[n, ci, di, hi, wi]
 258:                     // r_idx = (((((n*Cin + ci)*Din + di)*Hin + hi)*Win) + wi)
 259:                     mul.lo.u32 r_tmpA, r_n, rCin;
 260:                     add.u32    r_tmpA, r_tmpA, r_ci;
 261:                     mul.lo.u32 r_tmpA, r_tmpA, rDin;
 262:                     add.u32    r_tmpA, r_tmpA, r_di;
 263:                     mul.lo.u32 r_tmpA, r_tmpA, rHin;
 264:                     add.u32    r_tmpA, r_tmpA, r_hi;
 265:                     mul.lo.u32 r_tmpA, r_tmpA, rWin;
 266:                     add.u32    r_idx, r_tmpA, r_wii;
 267:                     mul.wide.u32 off, r_idx, 4;
 268:                     add.s64 addr, px, off;
 269:                     ld.global.f32 f_x, [addr];
 270:                     // Load staged w from shared memory: idx = in_cg*K^3 + kd*K^2 + kh*K + kw
 271:                     mul.lo.u32 r_tmpB, r_in_cg, rK3;
 272:                     mul.lo.u32 r_tmpC, r_kd, rK2;
 273:                     add.u32    r_tmpB, r_tmpB, r_tmpC;
 274:                     mul.lo.u32 r_tmpC, r_kh, rK;
 275:                     add.u32    r_tmpB, r_tmpB, r_tmpC;
 276:                     add.u32    r_tmpB, r_tmpB, r_kw;
 277:                     mul.wide.u32 off, r_tmpB, 4;
 278:                     add.s64 addr, smem_ptr, off;
 279:                     ld.shared.f32 f_w, [addr];
 280:                     // sum += x * w
 281:                     fma.rn.f32 f_sum, f_x, f_w, f_sum;
 282:                 L_NEXT_MW2:
 283:                     add.s32 m_w, m_w, 1;
 284:                     bra L_MW2;
 285:             L_END_MW2:
 286:             L_NEXT_MH2:
 287:                 add.s32 m_h, m_h, 1;
 288:                 bra L_MH2;
 289:         L_END_MH2:
 290:         L_NEXT_MD2:
 291:             add.s32 m_d, m_d, 1;
 292:             bra L_MD2;
 293:     L_END_MD2:
 294:         add.u32 r_in_cg, r_in_cg, 1;
 295:         bra L_IN_CG;
 296: L_END_IN_CG:
 297: SKIP_COMPUTE:
 298:     // Store y[n, co, do, ho, wo] for active threads
 299:     @!p_active bra RET;
 300:         // oidx = (((((n*Cout + co)*Dout + do)*Hout + ho)*Wout) + wo)
 301:         mul.lo.u32 r_tmpC, r_n, rCout;
 302:         add.u32    r_tmpC, r_tmpC, r_co;
 303:         mul.lo.u32 r_tmpC, r_tmpC, rDout;
 304:         add.u32    r_tmpC, r_tmpC, r_do;
 305:         mul.lo.u32 r_tmpC, r_tmpC, rHout;
 306:         add.u32    r_tmpC, r_tmpC, r_ho;
 307:         mul.lo.u32 r_tmpC, r_tmpC, rWout;
 308:         add.u32    r_tmpC, r_tmpC, r_wi;
 309:         mul.wide.u32 off, r_tmpC, 4;
 310:         add.s64 addr, py, off;
 311:         st.global.f32 [addr], f_sum;
 312: RET:
 313:     ret;
 314: }
